/**
 * chat 对话
 *
 * @fansili
 * @since v1.0
 */
@Service
@Slf4j
@AllArgsConstructor
public class AiChatConversationServiceImpl implements AiChatConversationService {

    private final AiChatModalMapper aiChatModalMapper;
    private final AiChatModalService aiChatModalService;
    private final AiChatRoleService aiChatRoleService;
    private final AiChatConversationMapper aiChatConversationMapper;

    @Override
    public Long createConversation(AiChatConversationCreateReqVO req) {
        // 获取用户id
        Long loginUserId = SecurityFrameworkUtils.getLoginUserId();
        // 默认使用 sort 排序第一个模型
        AiChatModalDO aiChatModalDO = aiChatModalMapper.selectFirstModal();
        // 查询角色
        AiChatRoleRes chatRoleRes = null;
        if (req.getRoleId() != null) {
            chatRoleRes = aiChatRoleService.getChatRole(req.getRoleId());
        }
        Long chatRoleId = chatRoleRes != null ? chatRoleRes.getId() : null;
        // 创建新的 Conversation
        AiChatConversationDO insertConversation = saveConversation(AiCommonConstants.CONVERSATION_DEFAULT_TITLE,
                loginUserId, chatRoleId, aiChatModalDO.getId(), aiChatModalDO.getModel()
        );
        // 返回对话id
        return insertConversation.getId();
    }

    private @NotNull AiChatConversationDO saveConversation(String title,
                                                           Long userId,
                                                           Long roleId,
                                                           Long modalId,
                                                           String model) {
        AiChatConversationDO insertConversation = new AiChatConversationDO();
        insertConversation.setId(null);
        insertConversation.setUserId(userId);
        insertConversation.setTitle(title);
        insertConversation.setPinned(false);

        insertConversation.setRoleId(roleId);
        insertConversation.setModelId(modalId);
        insertConversation.setModel(model);

        insertConversation.setTemperature(null);
        insertConversation.setMaxTokens(null);
        insertConversation.setMaxContexts(null);
        aiChatConversationMapper.insert(insertConversation);
        return insertConversation;
    }

    @Override
    public Boolean updateConversation(AiChatConversationUpdateReqVO updateReqVO) {
        // 校验对话是否存在
        validateExists(updateReqVO.getId());
        // 获取模型信息并验证
        AiChatModalRes chatModal = aiChatModalService.getChatModalOfValidate(updateReqVO.getModelId());
        // 校验modal是否可用
        validateAvailable(chatModal);
        // 更新对话信息
        AiChatConversationDO updateAiChatConversationDO
                = AiChatConversationConvert.INSTANCE.convertAiChatConversationDO(updateReqVO);
        return aiChatConversationMapper.updateById(updateAiChatConversationDO) > 0;
    }

    private void validateAvailable(AiChatModalRes chatModal) {
        if (AiChatModalDisableEnum.YES.getValue().equals(chatModal.getDisable())) {
            throw ServiceExceptionUtil.exception(ErrorCodeConstants.AI_MODAL_DISABLE_NOT_USED);
        }
    }

    @Override
    public List<AiChatConversationRespVO> listConversation(AiChatConversationListReqVO listReqVO) {
        // 获取用户id
        Long loginUserId = SecurityFrameworkUtils.getLoginUserId();
        // 查询前100对话
        List<AiChatConversationDO> top100Conversation
                = aiChatConversationMapper.selectTop100Conversation(loginUserId, listReqVO.getTitle());
        return AiChatConversationConvert.INSTANCE.covnertChatConversationResList(top100Conversation);
    }

    @Override
    public AiChatConversationRespVO getConversationOfValidate(Long id) {
        AiChatConversationDO aiChatConversationDO = validateExists(id);
        return AiChatConversationConvert.INSTANCE.covnertChatConversationRes(aiChatConversationDO);
    }

    @Override
    public Boolean deleteConversation(Long id) {
        return aiChatConversationMapper.deleteById(id) > 0;
    }

    private @NotNull AiChatConversationDO validateExists(Long id) {
        AiChatConversationDO aiChatConversationDO = aiChatConversationMapper.selectById(id);
        if (aiChatConversationDO == null) {
            throw ServiceExceptionUtil.exception(ErrorCodeConstants.AI_CONVERSATION_NOT_EXISTS);
        }
        return aiChatConversationDO;
    }
}

/**
 * midjourney job 定时拉去 midjourney 绘制状态
 *
 * @author fansili
 * @time 2024/6/5 14:55
 * @since 1.0
 */
@Component
@Slf4j
public class MidjourneyJob implements JobHandler {

    // TODO @fan：@Resource
    @Autowired
    private MidjourneyApi midjourneyApi;
    @Autowired
    private AiImageMapper imageMapper;
    @Autowired
    private AiImageService imageService;

    // TODO @fan：这个方法，建议实现到 AiImageService，例如说 midjourneySync，返回 int 同步数量。
    @Override
    public String execute(String param) throws Exception {
        // 1、获取 midjourney 平台，状态在 “进行中” 的 image
        // TODO @fan：43 和 51 其实有点重叠，日志，建议只打 51
        log.info("Midjourney 同步 - 开始...");
        // TODO @fan：Job、Service 等业务层，不要直接使用 LambdaUpdateWrapper，这样会导致 mapper 穿透到逻辑层。要收敛到 mapper 里。
        List<AiImageDO> imageList = selectByStatusAndPlatform();
        log.info("Midjourney 同步 - 任务数量 {}!", imageList.size());
        if (CollUtil.isEmpty(imageList)) {
            // TODO @fan：51 和 54，其实有点重叠。建议 51 挪到 55 之后打。
            return "Midjourney 同步 - 数量为空!";
        }
        // 2、批量拉去 task 信息
        // TODO @fan：imageList.stream().map(AiImageDO::getTaskId).collect(Collectors.toSet()))，可以使用 CollectionUtils.convertSet 简化
        List<MidjourneyApi.NotifyRequest> taskList = midjourneyApi
                .listByCondition(imageList.stream().map(AiImageDO::getTaskId).collect(Collectors.toSet()));
        // TODO @fan：taskList.stream().collect(Collectors.toMap(MidjourneyNotifyReqVO::getId, o -> o))，也可以使用 CollectionUtils.convertMap；本质上，重用 set、map 转换，要 convert 简化
        Map<String, MidjourneyApi.NotifyRequest> taskIdMap = taskList.stream().collect(Collectors.toMap(MidjourneyApi.NotifyRequest::id, o -> o));
        // 3、更新 image 状态
        List<AiImageDO> updateImageList = new ArrayList<>();
        for (AiImageDO aiImageDO : imageList) {
            // 3.1 排除掉空的情况
            if (!taskIdMap.containsKey(aiImageDO.getTaskId())) {
                log.warn("Midjourney 同步 - {} 任务为空!", aiImageDO.getTaskId());
                continue;
            }
            // TODO @ 3.1 和 3.2 是不是融合下；get，然后判空，continue；
            // 3.2 获取通知对象
//            MidjourneyNotifyReqVO notifyReqVO = taskIdMap.get(aiImageDO.getTaskId());
            // 3.2 构建更新对象
            // TODO @fan：建议 List<MidjourneyNotifyReqVO> 作为 imageService 去更新；
//            updateImageList.add(imageService.buildUpdateImage(aiImageDO.getId(), notifyReqVO));
        }
        // 4、批了更新 updateImageList
        imageMapper.updateBatch(updateImageList);
        return "Midjourney 同步 - ".concat(String.valueOf(updateImageList.size())).concat(" 任务!");
    }

    private List<AiImageDO> selectByStatusAndPlatform() {
        List<AiImageDO> imageList = imageMapper.selectList(
                new LambdaUpdateWrapper<AiImageDO>()
                        .eq(AiImageDO::getStatus, AiImageStatusEnum.IN_PROGRESS.getStatus())
                        .eq(AiImageDO::getPlatform, AiPlatformEnum.MIDJOURNEY.getPlatform())
        );
        return imageList;
    }

}

/**
 * 客服消息 Service 实现类
 *
 * @author HUIHUI
 */
@Service
@Validated
public class KeFuMessageServiceImpl implements KeFuMessageService {

    // TODO @puhui999：@芋艿：捉摸要不要拿到一个地方枚举；
    private static final String KEFU_MESSAGE_TYPE = "kefu_message_type"; // 客服消息类型

    // TODO @puhui999：kefuMessageMapper；因为 messageMapper 可能会重叠
    @Resource
    private KeFuMessageMapper messageMapper;

    @Resource
    private KeFuConversationService conversationService;

    @Resource
    private AdminUserApi adminUserApi;
    @Resource
    private MemberUserApi memberUserApi;
    @Resource
    private WebSocketSenderApi webSocketSenderApi;

    @Override
    @Transactional(rollbackFor = Exception.class)
    public Long sendKefuMessage(KeFuMessageSendReqVO sendReqVO) {
        // 1.1 校验会话是否存在
        KeFuConversationDO conversation = conversationService.validateKefuConversationExists(sendReqVO.getConversationId());
        // 1.2 校验接收人是否存在
        validateReceiverExist(sendReqVO.getReceiverId(), sendReqVO.getReceiverType());

        // 2.1 保存消息
        KeFuMessageDO kefuMessage = BeanUtils.toBean(sendReqVO, KeFuMessageDO.class);
        messageMapper.insert(kefuMessage);
        // TODO @puhui999：是不是 updateConversationMessage，里面统一处理未读、恢复；直接设置 KeFuMessageDO 作为参数好了。。。
        // 2.2 更新会话消息冗余
        conversationService.updateConversationMessage(kefuMessage.getConversationId(), LocalDateTime.now(),
                kefuMessage.getContent(), kefuMessage.getContentType());
        // 2.3 更新管理员未读消息数
        if (UserTypeEnum.ADMIN.getValue().equals(kefuMessage.getReceiverType())) {
            conversationService.updateAdminUnreadMessageCountByConversationId(kefuMessage.getConversationId(), 1);
        }
        // 2.4 会员用户发送消息时，如果管理员删除过会话则进行恢复
        // TODO @puhui999：建议 && 换一行
        updateConversationLastMessage(conversation, kefuMessage);

        // 3. 发送消息
        getSelf().sendAsyncMessage(sendReqVO.getReceiverType(), sendReqVO.getReceiverId(), kefuMessage);
        return kefuMessage.getId();
    }

    private void updateConversationLastMessage(KeFuConversationDO conversation, KeFuMessageDO kefuMessage) {
        if (UserTypeEnum.MEMBER.getValue().equals(kefuMessage.getSenderType()) && Boolean.TRUE.equals(conversation.getAdminDeleted())) {
            conversationService.updateConversationAdminDeleted(kefuMessage.getConversationId(), Boolean.FALSE);
        }
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void updateKefuMessageReadStatus(Long conversationId, Long receiverId) {
        // 1.1 校验会话是否存在
        conversationService.validateKefuConversationExists(conversationId);
        // 1.2 查询接收人所有的未读消息
        // TODO @puhui999：应该不能 receiverId 过滤哈。因为多个客服，一个人点了，就都点了。
        List<KeFuMessageDO> messageList = messageMapper.selectListByConversationIdAndReceiverIdAndReadStatus(
                conversationId, receiverId, Boolean.FALSE);
        // 1.3 情况一：没有未读消息
        if (CollUtil.isEmpty(messageList)) {
            return;
        }

        // 2.1 情况二：更新未读消息状态为已读
        messageMapper.updateReadStstusBatchByIds(convertSet(messageList, KeFuMessageDO::getId), Boolean.TRUE);
        // 2.2 更新管理员未读消息数
        KeFuMessageDO message = getFirst(messageList);
        assert message != null;
        if (UserTypeEnum.ADMIN.getValue().equals(message.getReceiverType())) {
            conversationService.updateAdminUnreadMessageCountByConversationId(conversationId, 0);
        }

        // 2.3 发送消息通知发送者，接收者已读 -> 发送者更新发送的消息状态
        // TODO @puhui999：待定~
        getSelf().sendAsyncMessage(message.getSenderType(), message.getSenderId(), "keFuMessageReadStatusChange");
    }

    private void validateReceiverExist(Long receiverId, Integer receiverType) {
        if (UserTypeEnum.ADMIN.getValue().equals(receiverType)) {
            adminUserApi.validateUser(receiverId);
        }
        if (UserTypeEnum.MEMBER.getValue().equals(receiverType)) {
            memberUserApi.validateUser(receiverId);
        }
    }

    @Async
    public void sendAsyncMessage(Integer userType, Long userId, Object content) {
        webSocketSenderApi.sendObject(userType, userId, KEFU_MESSAGE_TYPE, content);
    }

    @Override
    public PageResult<KeFuMessageDO> getKefuMessagePage(KeFuMessagePageReqVO pageReqVO) {
        return messageMapper.selectPage(pageReqVO);
    }

    private KeFuMessageServiceImpl getSelf() {
        return SpringUtil.getBean(getClass());
    }

}

/**
 * 客服会话 Service 实现类
 *
 * @author HUIHUI
 */
@Service
@Validated
public class KeFuConversationServiceImpl implements KeFuConversationService {

    @Resource
    private KeFuConversationMapper conversationMapper;

    @Override
    public void deleteKefuConversation(Long id) {
        // 校验存在
        validateKefuConversationExists(id);

        // 只有管理员端可以删除会话，也不真的删，只是管理员端看不到啦
        conversationMapper.updateById(new KeFuConversationDO().setId(id).setAdminDeleted(Boolean.TRUE));
    }

    @Override
    public void updateConversationPinnedByAdmin(KeFuConversationUpdatePinnedReqVO updateReqVO) {
        conversationMapper.updateById(new KeFuConversationDO().setId(updateReqVO.getId()).setAdminPinned(updateReqVO.getAdminPinned()));
    }

    @Override
    @Transactional(rollbackFor = Exception.class)
    public void updateConversationLastMessage(KeFuMessageDO kefuMessage) {
        // 1.1 校验会话是否存在
        KeFuConversationDO conversation = validateKefuConversationExists(kefuMessage.getConversationId());
        // 1.2 更新会话消息冗余
        conversationMapper.updateById(new KeFuConversationDO().setId(kefuMessage.getConversationId())
                .setLastMessageTime(kefuMessage.getCreateTime()).setLastMessageContent(kefuMessage.getContent())
                .setLastMessageContentType(kefuMessage.getContentType()));

        // 2.1 更新管理员未读消息数
        if (UserTypeEnum.MEMBER.getValue().equals(kefuMessage.getSenderType())) {
            conversationMapper.updateAdminUnreadMessageCount(kefuMessage.getConversationId());
        }
        // 2.2 会员用户发送消息时，如果管理员删除过会话则进行恢复
        // TODO @puhui999：其实不用判断用户类型；只要be已删除，就恢复！
        if (UserTypeEnum.MEMBER.getValue().equals(kefuMessage.getSenderType())
                && Boolean.TRUE.equals(conversation.getAdminDeleted())) {
            updateConversationAdminDeleted(kefuMessage.getConversationId(), Boolean.FALSE);
        }
    }

    @Override
    public void updateAdminUnreadMessageCountWithZero(Long id) {
        validateKefuConversationExists(id);
        conversationMapper.updateAdminUnreadMessageCountWithZero(id);
    }

    @Override
    public void updateConversationAdminDeleted(Long id, Boolean adminDeleted) {
        conversationMapper.updateById(new KeFuConversationDO().setId(id).setAdminDeleted(adminDeleted));
    }

    @Override
    public List<KeFuConversationDO> getKefuConversationList() {
        return conversationMapper.selectConversationList();
    }

    @Override
    public KeFuConversationDO getOrCreateConversation(Long userId) {
        KeFuConversationDO conversation = conversationMapper.selectOne(KeFuConversationDO::getUserId, userId);
        // 没有历史会话，则初始化一个新会话
        if (conversation == null) {
            conversation = new KeFuConversationDO().setUserId(userId).setLastMessageTime(LocalDateTime.now())
                    .setLastMessageContent(StrUtil.EMPTY).setLastMessageContentType(KeFuMessageContentTypeEnum.TEXT.getType())
                    .setAdminPinned(Boolean.FALSE).setUserDeleted(Boolean.FALSE).setAdminDeleted(Boolean.FALSE)
                    .setAdminUnreadMessageCount(0);
            conversationMapper.insert(conversation);
        }
        return conversation;
    }

    @Override
    public KeFuConversationDO validateKefuConversationExists(Long id) {
        KeFuConversationDO conversation = conversationMapper.selectById(id);
        if (conversation == null) {
            throw exception(KEFU_CONVERSATION_NOT_EXISTS);
        }
        return conversation;
    }

    @Override
    public KeFuConversationDO getConversationByUserId(Long userId) {
        // TODO @puhui999：service 不写 dao 的逻辑哈
        return selectByUserId(userId);
    }

    private KeFuConversationDO selectByUserId(Long userId) {
        return conversationMapper.selectOne(KeFuConversationDO::getUserId, userId);
    }

}

@Tag(name = "管理后台 - 商品浏览记录")
@RestController
@RequestMapping("/product/browse-history")
@Validated
public class ProductBrowseHistoryController {

    @Resource
    private ProductBrowseHistoryService browseHistoryService;
    @Resource
    private ProductSpuService productSpuService;

    @GetMapping("/page")
    @Operation(summary = "获得商品浏览记录分页")
    @PreAuthorize("@ss.hasPermission('product:browse-history:query')")
    public CommonResult<PageResult<ProductBrowseHistoryRespVO>> getBrowseHistoryPage(@Valid ProductBrowseHistoryPageReqVO pageReqVO) {
        PageResult<ProductBrowseHistoryDO> pageResult = browseHistoryService.getBrowseHistoryPage(pageReqVO);
        if (CollUtil.isEmpty(pageResult.getList())) {
            return success(PageResult.empty());
        }

        // 得到商品 spu 信息
        Set<Long> spuIds = convertSet(pageResult.getList(), ProductBrowseHistoryDO::getSpuId);
        Map<Long, ProductSpuDO> spuMap = getSpuMap(spuIds);
        return success(BeanUtils.toBean(pageResult, ProductBrowseHistoryRespVO.class,
                vo -> Optional.ofNullable(spuMap.get(vo.getSpuId()))
                        .ifPresent(spu -> vo.setSpuName(spu.getName()).setPicUrl(spu.getPicUrl()).setPrice(spu.getPrice()))));
    }

    private Map<Long, ProductSpuDO> getSpuMap(Set<Long> spuIds) {
        Map<Long, ProductSpuDO> spuMap = convertMap(productSpuService.getSpuList(spuIds), ProductSpuDO::getId);
        return spuMap;
    }

}

